// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetApplicationConfig Read application configuration
	// (GET /applications/{applicationId}/config)
	GetApplicationConfig(ctx context.Context, request GetApplicationConfigRequestObject) (GetApplicationConfigResponseObject, error)
	// UpdateApplicationConfig Update application configuration
	// (PUT /applications/{applicationId}/config)
	UpdateApplicationConfig(ctx context.Context, request UpdateApplicationConfigRequestObject) (UpdateApplicationConfigResponseObject, error)
	// CheckAuthorization Check one permission decision
	// (POST /authorize)
	CheckAuthorization(ctx context.Context, request CheckAuthorizationRequestObject) (CheckAuthorizationResponseObject, error)
	// CheckAuthorizationBatch Check ordered permission decisions
	// (POST /authorize/batch)
	CheckAuthorizationBatch(ctx context.Context, request CheckAuthorizationBatchRequestObject) (CheckAuthorizationBatchResponseObject, error)
	// ListBindings List role bindings
	// (GET /bindings)
	ListBindings(ctx context.Context, request ListBindingsRequestObject) (ListBindingsResponseObject, error)
	// CreateBinding Bind a role to a user or group
	// (POST /bindings)
	CreateBinding(ctx context.Context, request CreateBindingRequestObject) (CreateBindingResponseObject, error)
	// DeleteBinding Remove a role binding
	// (DELETE /bindings/{bindingId})
	DeleteBinding(ctx context.Context, request DeleteBindingRequestObject) (DeleteBindingResponseObject, error)
	// ListGroups List groups and memberships
	// (GET /groups)
	ListGroups(ctx context.Context, request ListGroupsRequestObject) (ListGroupsResponseObject, error)
	// CreateGroup Create a group
	// (POST /groups)
	CreateGroup(ctx context.Context, request CreateGroupRequestObject) (CreateGroupResponseObject, error)
	// RemoveGroupMember Remove a user from a group
	// (DELETE /groups/{groupId}/members)
	RemoveGroupMember(ctx context.Context, request RemoveGroupMemberRequestObject) (RemoveGroupMemberResponseObject, error)
	// AddGroupMember Add a user to a group
	// (POST /groups/{groupId}/members)
	AddGroupMember(ctx context.Context, request AddGroupMemberRequestObject) (AddGroupMemberResponseObject, error)
	// GetHealth Check server and authorization-engine readiness
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GrantLegacyAccess Grant coarse model access through a compatibility role
	// (POST /legacy/grants)
	GrantLegacyAccess(ctx context.Context, request GrantLegacyAccessRequestObject) (GrantLegacyAccessResponseObject, error)
	// RevokeLegacyAccess Downgrade or remove a coarse model compatibility role
	// (POST /legacy/revokes)
	RevokeLegacyAccess(ctx context.Context, request RevokeLegacyAccessRequestObject) (RevokeLegacyAccessResponseObject, error)
	// SSHMachine Simulate an SSH session to a machine
	// (POST /machines/{machineId}/ssh)
	SSHMachine(ctx context.Context, request SSHMachineRequestObject) (SSHMachineResponseObject, error)
	// ListPermissions List the permission catalogue
	// (GET /permissions)
	ListPermissions(ctx context.Context, request ListPermissionsRequestObject) (ListPermissionsResponseObject, error)
	// ListResources List readable resources
	// (GET /resources)
	ListResources(ctx context.Context, request ListResourcesRequestObject) (ListResourcesResponseObject, error)
	// CreateResource Create a resource under an authorized parent
	// (POST /resources)
	CreateResource(ctx context.Context, request CreateResourceRequestObject) (CreateResourceResponseObject, error)
	// DeleteResource Delete an authorized leaf resource
	// (DELETE /resources/{resourceType}/{resourceId})
	DeleteResource(ctx context.Context, request DeleteResourceRequestObject) (DeleteResourceResponseObject, error)
	// GetResource Get readable resource details
	// (GET /resources/{resourceType}/{resourceId})
	GetResource(ctx context.Context, request GetResourceRequestObject) (GetResourceResponseObject, error)
	// ListRoles List built-in and custom roles
	// (GET /roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// CreateRole Create a mutable custom role
	// (POST /roles)
	CreateRole(ctx context.Context, request CreateRoleRequestObject) (CreateRoleResponseObject, error)
	// GetRole Get a role
	// (GET /roles/{roleId})
	GetRole(ctx context.Context, request GetRoleRequestObject) (GetRoleResponseObject, error)
	// UpdateRole Update a custom role at an expected revision
	// (PUT /roles/{roleId})
	UpdateRole(ctx context.Context, request UpdateRoleRequestObject) (UpdateRoleResponseObject, error)
	// PreviewRoleUpdate Preview the impact of a custom role update
	// (POST /roles/{roleId}/preview)
	PreviewRoleUpdate(ctx context.Context, request PreviewRoleUpdateRequestObject) (PreviewRoleUpdateResponseObject, error)
	// SSHUnit Simulate an SSH session to a unit
	// (POST /units/{unitId}/ssh)
	SSHUnit(ctx context.Context, request SSHUnitRequestObject) (SSHUnitResponseObject, error)
	// ListUsers List demo users
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Create a demo user
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

